class CompanySetting extends DataClass implements Insertable<CompanySetting> {
  final String id;
  final String companyName;
  final String warehouseTopology;
  final String? centralWarehouseShopId;
  final DateTime updatedAt;
  const CompanySetting(
      {required this.id,
      required this.companyName,
      required this.warehouseTopology,
      this.centralWarehouseShopId,
      required this.updatedAt});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['company_name'] = Variable<String>(companyName);
    map['warehouse_topology'] = Variable<String>(warehouseTopology);
    if (!nullToAbsent || centralWarehouseShopId != null) {
      map['central_warehouse_shop_id'] =
          Variable<String>(centralWarehouseShopId);
    }
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  CompanySettingsCompanion toCompanion(bool nullToAbsent) {
    return CompanySettingsCompanion(
      id: Value(id),
      companyName: Value(companyName),
      warehouseTopology: Value(warehouseTopology),
      centralWarehouseShopId: centralWarehouseShopId == null && nullToAbsent
          ? const Value.absent()
          : Value(centralWarehouseShopId),
      updatedAt: Value(updatedAt),
    );
  }

  factory CompanySetting.fromJson(Map<String, dynamic> json,
      {ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return CompanySetting(
      id: serializer.fromJson<String>(json['id']),
      companyName: serializer.fromJson<String>(json['companyName']),
      warehouseTopology: serializer.fromJson<String>(json['warehouseTopology']),
      centralWarehouseShopId:
          serializer.fromJson<String?>(json['centralWarehouseShopId']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'companyName': serializer.toJson<String>(companyName),
      'warehouseTopology': serializer.toJson<String>(warehouseTopology),
      'centralWarehouseShopId':
          serializer.toJson<String?>(centralWarehouseShopId),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
    };
  }

  CompanySetting copyWith(
          {String? id,
          String? companyName,
          String? warehouseTopology,
          Value<String?> centralWarehouseShopId = const Value.absent(),
          DateTime? updatedAt}) =>
      CompanySetting(
        id: id ?? this.id,
        companyName: companyName ?? this.companyName,
        warehouseTopology: warehouseTopology ?? this.warehouseTopology,
        centralWarehouseShopId: centralWarehouseShopId.present
            ? centralWarehouseShopId.value
            : this.centralWarehouseShopId,
        updatedAt: updatedAt ?? this.updatedAt,
      );
  CompanySetting copyWithCompanion(CompanySettingsCompanion data) {
    return CompanySetting(
      id: data.id.present ? data.id.value : this.id,
      companyName:
          data.companyName.present ? data.companyName.value : this.companyName,
      warehouseTopology: data.warehouseTopology.present
          ? data.warehouseTopology.value
          : this.warehouseTopology,
      centralWarehouseShopId: data.centralWarehouseShopId.present
          ? data.centralWarehouseShopId.value
          : this.centralWarehouseShopId,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
    );
  }

