  final bool mustChangePassword;
  final DateTime? lastLoginAt;
  final int version;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  final bool isDirty;
  const User(
      {required this.id,
      required this.email,
      required this.passwordHash,
      this.pinCodeHash,
      required this.firstName,
      required this.lastName,
      this.phone,
