    if (!nullToAbsent || pinCodeHash != null) {
      map['pin_code_hash'] = Variable<String>(pinCodeHash);
    }
    map['first_name'] = Variable<String>(firstName);
    map['last_name'] = Variable<String>(lastName);
    if (!nullToAbsent || phone != null) {
      map['phone'] = Variable<String>(phone);
    }
    if (!nullToAbsent || avatarUrl != null) {
      map['avatar_url'] = Variable<String>(avatarUrl);
    }
    map['global_role'] = Variable<String>(globalRole);
    map['commission_rate_percent'] = Variable<double>(commissionRatePercent);
    map['is_active'] = Variable<bool>(isActive);
    map['must_change_password'] = Variable<bool>(mustChangePassword);
    if (!nullToAbsent || lastLoginAt != null) {
      map['last_login_at'] = Variable<DateTime>(lastLoginAt);
    }
    map['version'] = Variable<int>(version);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['is_dirty'] = Variable<bool>(isDirty);
    return map;
  }

  UsersCompanion toCompanion(bool nullToAbsent) {
    return UsersCompanion(
      id: Value(id),
      email: Value(email),
      passwordHash: Value(passwordHash),
      pinCodeHash: pinCodeHash == null && nullToAbsent
          ? const Value.absent()
          : Value(pinCodeHash),
      firstName: Value(firstName),
      lastName: Value(lastName),
      phone:
          phone == null && nullToAbsent ? const Value.absent() : Value(phone),
      avatarUrl: avatarUrl == null && nullToAbsent
          ? const Value.absent()
          : Value(avatarUrl),
      globalRole: Value(globalRole),
      commissionRatePercent: Value(commissionRatePercent),
      isActive: Value(isActive),
      mustChangePassword: Value(mustChangePassword),
      lastLoginAt: lastLoginAt == null && nullToAbsent
