          ..write('totalSalesCents: $totalSalesCents, ')
          ..write('totalDepositsCents: $totalDepositsCents, ')
          ..write('totalCashInCents: $totalCashInCents, ')
          ..write('totalCashOutCents: $totalCashOutCents, ')
          ..write('totalMobileMoneyCents: $totalMobileMoneyCents, ')
          ..write('totalCardCents: $totalCardCents, ')
          ..write('totalCreditSalesCents: $totalCreditSalesCents, ')
          ..write('notes: $notes, ')
          ..write('version: $version, ')
          ..write('updatedAt: $updatedAt, ')
          ..write('isDirty: $isDirty, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

